        AND sp.part_name LIKE '%' || #{params.partName} || '%'


        AND sp.category = #{params.category}


        AND sp.supply_point_id = #{params.supplyPointId}


        AND sp.stock_quantity <= sp.warning_threshold


ORDER BY sp.create_time DESC


WHERE sp.stock_quantity > 0
AND sp.id NOT IN (
    SELECT DISTINCT part_id FROM stock_record
    WHERE operate_time >= #{deadStockDate}
)
ORDER BY sp.stock_quantity DESC

SELECT COUNT(*) FROM spare_part
WHERE stock_quantity > 0
AND id NOT IN (
    SELECT DISTINCT part_id FROM stock_record
    WHERE operate_time >= #{deadStockDate}
)
